/**
 * 负责按配置开启白天自爆机会，并捕获原存活玩家。输入为窗口、Provider 与 Gateway；输出为接受的自爆选择或原窗口结果。只有仍有效的原玩家可以提交，不以替换身体恢复机会。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RED_MOON_ROLE } from "../mechanisms/roles/red_moon_apostle/ports";
import { demonRedMoonCanBlast } from "../mechanisms/roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../mechanisms/roles/self_destruct_capability";
import { getDefaultRoleCatalog } from "../mechanisms/roles/role-catalog-assembly";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
} from "../mechanisms/roles/ghost_bride/authority";
import { AliveComponent, aliveLifeVersion } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionProvider,
  ActionWindow,
  Phase,
  type SelfDestructSelection,
} from "../../core/domain/model";
import { RoleRegistry } from "../../core/domain/registries/role_registry";
import { World } from "../../core/domain/world";
import { ToolGateway } from "../gateway/tool_gateway";
import { GameActionRequestFactory } from "./action_request_factory";
import { getWhiteWolfKingState } from "../mechanisms/roles/white_wolf_king/ports";

/** Collect choices concurrently, then commit only the lowest-ID still-valid choice. */
export class SelfDestructWindow {
  constructor(
    private readonly world: World,
    private readonly roleRegistry: RoleRegistry,
    private readonly toolGateway: ToolGateway,
  ) {}

  async execute(
    requests: GameActionRequestFactory,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent: () => boolean = () => true,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null> {
    if (!isCurrent()) return null;
    const targets = new Map(
      this.world.getAliveEntityIds().map((id) => {
        const alive = this.world.getComponent(id, COMPONENT.Alive)!;
        return [id, { alive, version: aliveLifeVersion(alive) }] as const;
      }),
    );
    const picks = await Promise.all(
      this.world.getAliveEntityIds().map(async (actorId) => {
        const role = this.world.getComponent(actorId, COMPONENT.Role);
        if (!role) return null;
        if (
          weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, role))
        )
          return null;
        const tools = this.roleRegistry.getAllowedTools(role.role);
        const tool = tools.includes("self_destruct_with_target")
          ? "self_destruct_with_target"
          : tools.includes("self_destruct")
            ? "self_destruct"
            : null;
        if (!tool) return null;
        if (
          tool === "self_destruct" &&
          (String(role.role) === RED_MOON_ROLE
            ? !demonRedMoonCanBlast(this.world, actorId)
            : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
        )
          return null;
        const resource =
          tool === "self_destruct_with_target" ? getWhiteWolfKingState(role) : undefined;
        if (tool === "self_destruct_with_target" && resource?.canDetonate !== true) return null;
        const life = targets.get(actorId)!;
        const request = requests.create({
          phase,
          actionWindow: window,
          actorId,
          allowedTools: [tool],
          stage: window,
          requiresAction: false,
          summary: {
            key:
              phase === Phase.Voting
                ? "request.summary.self_destruct_pre_vote"
                : "request.summary.self_destruct",
          },
          context: {},
        });
        const action = await provider.getAction(request);
        if (
          action?.name !== tool ||
          (action.name !== "self_destruct" && action.name !== "self_destruct_with_target")
        )
          return null;
        const choice: SelfDestructSelection =
          action.name === "self_destruct"
            ? { kind: "ordinary", actorId, targetId: null }
            : { kind: "white_wolf_king", actorId, targetId: action.args.target_id };
        return { choice, action, role, resource, life };
      }),
    );
    if (!isCurrent()) return null;
    const stillCurrent = (pick: NonNullable<(typeof picks)[number]>) => {
      const { actorId, targetId } = pick.choice;
      if (
        !isCurrent() ||
        (weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, pick.role))) ||
        this.world.getComponent(actorId, COMPONENT.Role) !== pick.role ||
        this.world.getComponent(actorId, COMPONENT.Alive) !== pick.life.alive ||
        !pick.life.alive.alive ||
        pick.life.version === undefined ||
        aliveLifeVersion(pick.life.alive) !== pick.life.version
      )
        return false;
      if (String(pick.role.role) === RED_MOON_ROLE && !demonRedMoonCanBlast(this.world, actorId))
        return false;
      if (
        pick.choice.kind === "white_wolf_king" &&
        (getWhiteWolfKingState(pick.role) !== pick.resource || pick.resource?.canDetonate !== true)
      )
        return false;
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          this.world.getComponent(targetId, COMPONENT.Alive) !== target.alive ||
          !target.alive.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.alive) !== target.version
        )
          return false;
      }
      return true;
    };
    const valid = picks.filter(
      (pick): pick is NonNullable<typeof pick> =>
        pick !== null &&
        stillCurrent(pick) &&
        this.toolGateway.validateAndSanitize(this.world, pick.choice.actorId, pick.action, {
          phase,
          actionWindow: window,
          allowSelfDestruct: true,
        }).ok &&
        stillCurrent(pick),
    );
    for (const pick of valid.sort((a, b) => a.choice.actorId - b.choice.actorId)) {
      if (!isCurrent()) return null;
      if (!stillCurrent(pick)) continue;
      if ((await commit?.(pick.choice)) === false) continue;
      return pick.choice;
    }
    return null;
  }
}

export function isSelfDestructWindowEnabled(
  config: ReadonlyBoardConfig,
  window: ActionWindow,
): boolean {
  return config.selfDestruct?.enabledWindows === undefined
    ? window === ActionWindow.OnPreVote
    : config.selfDestruct.enabledWindows.includes(window);
}

/**
 * 负责通过配置的角色 hook 提交已选自爆。输入为捕获玩家、已校验选择和当前窗口；输出为原爆炸效果与死亡提案。不复用已撤销玩家，不执行最终阶段／胜负封盘。
 */
import { RED_MOON_ROLE } from "../roles/red_moon_apostle/ports";
import { commitDemonRedMoonBlast } from "../roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../roles/self_destruct_capability";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  swallowWeddingBadges,
} from "../roles/ghost_bride/authority";
import {
  ActionWindow,
  Phase,
  Role,
  DeathCause,
  type SelfDestructSelection,
  type DeathSources,
  type GameEvent,
} from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "../roles/white_wolf_king/ports";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** Commits only this public ability's resource/event/facts; the resolver owns death writes. */
export function commitSelfDestructSelection(
  world: World,
  choice: SelfDestructSelection,
  window: ActionWindow,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources } | null {
  if (
    !Object.values(ActionWindow).includes(window) ||
    phase !== (window === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day)
  )
    return null;
  const role = world.getComponent(choice.actorId, COMPONENT.Role);
  if (!role || !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive) return null;
  const ownsWedding = weddingSetup(world) !== null;
  if (
    ownsWedding &&
    (!ghostBrideReady(world) ||
      role.role !== Role.Wolf ||
      weddingMember(world, role) ||
      ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window))
  )
    return null;
  const deaths = [choice.actorId],
    sources: DeathSources = { [choice.actorId]: [DeathCause.SelfDestruct] };
  if (choice.kind === "ordinary") {
    const redMoon = String(role.role) === RED_MOON_ROLE;
    if (
      choice.targetId !== null ||
      (redMoon
        ? ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window)
        : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
    )
      return null;
    const moon = redMoon ? commitDemonRedMoonBlast(world, choice.actorId) : null;
    if (redMoon && !moon) return null;
    if (ownsWedding) swallowWeddingBadges(world, events);
    events.push({
      timestamp: Date.now(),
      type: "wolf_self_destruct",
      payload: { wolfId: choice.actorId, window },
    });
    if (moon?.sealsNight)
      events.push({
        timestamp: Date.now(),
        type: "red_moon_night_sealed",
        payload: { actorId: choice.actorId, day: moon.day, night: moon.day + 1 },
      });
  } else if (choice.kind === "white_wolf_king") {
    const state = getWhiteWolfKingState(role);
    if (role.role !== Role.WhiteWolfKing || state?.canDetonate !== true) return null;
    if (choice.targetId !== null) {
      if (
        choice.targetId === choice.actorId ||
        !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
      )
        return null;
      deaths.push(choice.targetId);
      sources[choice.targetId] = [DeathCause.WhiteWolfBlast];
    }
    consumeWhiteWolfDetonation(state);
    events.push({
      timestamp: Date.now(),
      type: "white_wolf_king_self_destruct",
      payload: { actorId: choice.actorId, targetId: choice.targetId, window },
    });
  } else return null;
  return { deaths, sources };
}
